<?php defined('ABSPATH') || exit;$base=home_url('/companion/');$root='dungeon-master/campaigns/'.$campaign->id().'/personae';$active=array_values(array_filter($personae??[],static fn($p):bool=>!$p->isArchived()));$archived=array_values(array_filter($personae??[],static fn($p):bool=>$p->isArchived()));$people=array_values(array_filter($active,static fn($p):bool=>!$p->isFaction()));$factions=array_values(array_filter($active,static fn($p):bool=>$p->isFaction()));$byId=[];foreach(($personae??[]) as $item){$byId[$item->id()]=$item;} ?>
<section class="gmrc-personae" aria-labelledby="gmrc-personae-title"><header class="gmrc-personae__hero"><div><p class="gmrc-dm-desk__eyebrow">Keeper’s Workshop · Dramatis Personae</p><h1 id="gmrc-personae-title">Dramatis Personae</h1><p>Keep the people, powers and factions of <strong><?php echo esc_html($campaign->name()); ?></strong> close to the campaign that owns them.</p></div><?php if(!$campaign->isArchived()): ?><a class="gmrc-personae-button" href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/create',$base)); ?>">Record Person or Faction</a><?php endif; ?></header><?php if(($flash['success']??null)): ?><p class="gmrc-personae-flash" role="status"><?php echo esc_html($flash['success']); ?></p><?php endif; ?>
<nav class="gmrc-personae-summary" aria-label="Dramatis Personae summary"><span><strong><?php echo count($people); ?></strong> people</span><span><strong><?php echo count($factions); ?></strong> factions</span><span><strong><?php echo count(array_filter($active,static fn($p):bool=>$p->visibility()==='players')); ?></strong> player-visible</span></nav>
<?php if($active===[]): ?><article class="gmrc-personae-empty"><div aria-hidden="true">🎭</div><h2>The cast list is waiting</h2><p>Record an NPC, patron, rival, witness, villain or faction. These identities can later be pinned to the Conspiracy Board without duplicating their campaign records.</p></article><?php else: ?><div class="gmrc-personae-grid"><?php foreach($active as $persona): ?><article class="gmrc-personae-card"><div class="gmrc-personae-card__meta"><span><?php echo esc_html($persona->kindLabel()); ?></span><span><?php echo $persona->isKeeperOnly()?'🔒 Keeper only':'◉ Player-visible'; ?></span></div><h2><?php echo esc_html($persona->name()); ?></h2><?php if($persona->role()!==''): ?><p class="gmrc-personae-card__role"><?php echo esc_html($persona->role()); ?></p><?php endif; ?><?php if($persona->factionId()!==''&&isset($byId[$persona->factionId()])): ?><p class="gmrc-personae-card__faction">With <?php echo esc_html($byId[$persona->factionId()]->name()); ?></p><?php endif; ?><p><?php echo esc_html($persona->summary()!==''?$persona->summary():'No at-a-glance description has been written yet.'); ?></p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$persona->id(),$base)); ?>">Open record <span aria-hidden="true">→</span></a></article><?php endforeach; ?></div><?php endif; ?>
<?php if($archived!==[]): ?><details class="gmrc-personae-archive"><summary>Archived records (<?php echo count($archived); ?>)</summary><div class="gmrc-personae-grid"><?php foreach($archived as $persona): ?><article class="gmrc-personae-card"><h2><?php echo esc_html($persona->name()); ?></h2><p><?php echo esc_html($persona->kindLabel()); ?> · Archived</p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$persona->id(),$base)); ?>">Read archived record</a></article><?php endforeach; ?></div></details><?php endif; ?><p class="gmrc-personae-back"><a href="<?php echo esc_url(add_query_arg('gmrc_route','dungeon-master/campaigns/'.$campaign->id(),$base)); ?>">← Back to Campaign Command Centre</a></p></section>
